def seq(S):
    na, nb = len(S['CA']), len(S['CB'])
    q = [('E', 0)] + [('C', i) for i in range(na)] + [('E', 1)] + [('C', na + i) for i in range(4)] + [('E', 2)] + \
        [('C', na + 4), ('C', na + 5), ('E', 5)] + [('C', na + nb + i) for i in range(3)] + [('E', 6)] + \
        [('C', na + nb + 3 + i) for i in range(3)] + [('E', 3), ('C', na + 6), ('C', na + 7), ('E', 4)]
    drop = S.get('drop', [])
    return [x for x in q if x not in drop]

STRUCT = ("STRUCTURE MODÈLE", ["Intro : contexte + avis annoncé", "Arguments, puis la nuance", "Une conclusion qui reprend l'avis"])
def _E(sujet, e1, e2, e5, e6):
    return [sujet + " Vous avez quatre minutes trente. C'est à vous.", e1, e2,
            "Il nous reste trente secondes. Pouvez-vous conclure ?", "Merci beaucoup. L'épreuve est terminée.", e5, e6]

